<template>
  <PageTitle title="Assignments" size="sm">
    <ProjectAssignmentsCreateAssignment
      v-if="assignableProject"
      :project="assignableProject"
      :users="assignableUserItems"
      :users-loading="isLoadingAssignableUsers"
      :assignments-params="params"
    />
    <ExportUsersList export-type="byProject" :project-id="projectId" :disabled="allCount === 0" />
  </PageTitle>
  <ProjectAssignmentsProjectOnboardingAlert
    :missing-counts="projectOnboardingMissingCounts"
    :project-id="projectId"
    class="mb-4"
  />
  <ProjectAssignmentsOnboardingAlert :missing-counts="onboardingMissingCounts" :project-id="projectId" class="mb-4" />
  <ProjectAssignmentFilters :params="params" :project-id="projectId" :project-type="projectShortInfo?.type" />
  <FilterTabsNav :items="statusTabs" rounded show-zero-count stretched />
  <Card>
    <CardContent class="!p-0 md:!p-0">
      <AppLoader v-if="isLoading" variant="inline" subject="assignments" />
      <AppError
        v-else-if="error"
        title="Failed to load assignments"
        :error="error"
        variant="table"
        :action="refetch"
        action-text="Retry"
      />
      <template v-else>
        <ResponsiveTable rounded>
          <ResponsiveTableHeader>
            <ResponsiveTableHead class="text-accent-foreground text-xs sm:text-sm leading-6">User </ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Status</ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Pay rate</ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Onboarding State</ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Project Onboarding State</ResponsiveTableHead>
            <ResponsiveTableHead class="text-center w-fit text-nowrap">Contract status</ResponsiveTableHead>
          </ResponsiveTableHeader>
          <ResponsiveTableBody>
            <ResponsiveTableEmpty
              v-if="(totalCount === 0 || items.length === 0) && !isLoading"
              :colspan="6"
              :cols="4"
              :cols-sm="4"
              cell-class="text-center"
            >
              <AppEmpty subject="assignments" variant="table" />
            </ResponsiveTableEmpty>
            <ResponsiveTableRow
              v-for="item in items"
              v-else
              :key="item.id"
              :to="{
                name: 'assignments-project_id-user_id',
                params: { project_id: projectId, user_id: item.id },
              }"
            >
              <ResponsiveTableCell :cols="4" :cols-sm="4" label="User">
                <div class="text-base flex items-center gap-4 sm:gap-2">
                  <AvatarImageWrapper
                    :src="item.profile_picture_url || ''"
                    alt="Profile Image"
                    :fallback="`${item.first_name.charAt(0)}${item.last_name.charAt(0)}`"
                    size="sm"
                  />
                  <div class="flex flex-col gap-1">
                    <h3 class="font-medium line-clamp-2">{{ item.first_name }} {{ item.last_name }}</h3>
                    <span class="capitalize text-muted-foreground text-sm">{{
                      snakeCaseToCapitalizedCase(item.role)
                    }}</span>
                  </div>
                </div>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="4" :cols-sm="2" label="Status">
                <div
                  v-if="
                    (item.role === 'canvasser' || item.role === 'subcontractor_canvasser') && item.assignment_status
                  "
                  class="flex md:justify-center"
                >
                  <Badge :variant="getAssignmentStatus(item.assignment_status).variant">
                    {{ getAssignmentStatus(item.assignment_status).name }}
                  </Badge>
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="1" label="Pay rate">
                <div v-if="item.role === 'canvasser'" class="flex flex-col md:items-center">
                  <p class="text-base font-medium">
                    ${{ projectShortInfo?.type === 'canvassing' ? item.price_per_hour : item.price_per_signature }}
                    <span v-if="typeof item.increased_price_per_hour === 'number'">
                      / {{ projectShortInfo?.type === 'canvassing' ? `$${item.increased_price_per_hour}` : '-' }}
                    </span>
                  </p>
                  <span v-if="item.assignment_type" class="text-xs text-muted-foreground">{{
                    getAssignmentType(item.assignment_type).shortName
                  }}</span>
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="1" label="Onboarding State">
                <div
                  v-if="item.onboarding_state && (item.role === 'canvasser' || item.role === 'subcontractor_canvasser')"
                  class="flex md:justify-center"
                >
                  <OnboardingState :onboarding-state="item.onboarding_state" />
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="1" label="Project Onboarding State">
                <div
                  v-if="
                    item.project_onboarding_state &&
                    (item.role === 'canvasser' || item.role === 'subcontractor_canvasser')
                  "
                  class="flex md:justify-center"
                >
                  <ProjectOnboardingStateHover :onboarding-state="item.project_onboarding_state" />
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
              <ResponsiveTableCell :cols="2" :cols-sm="2" label="Contract status">
                <div v-if="item.role === 'canvasser' && item.latest_contract_status" class="flex md:justify-center">
                  <Badge :variant="getContractStatus(item.latest_contract_status).variant">
                    {{ getContractStatus(item.latest_contract_status).name }}
                  </Badge>
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
            </ResponsiveTableRow>
          </ResponsiveTableBody>
          <ResponsiveTableFooter v-if="totalCount > 0 && items.length > 0" :colspan="6" :cols="4" :cols-sm="4">
            <AppPagination :page="params.page" :size="params.size" :total="totalCount" label="users" />
          </ResponsiveTableFooter>
        </ResponsiveTable>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import {
  type AssignmentStatus,
  type AssignmentType,
  type ContractStatus,
  getProjectCanvasserList,
  getProjectDetails,
  getSelectorUserList,
  type ProjectShortInfo,
  type SortType,
  type UserRole,
  type UserSortBy,
  type ProjectEditTabsStatusResponse,
  type ProjectCanvasserListRequest,
} from '~/client';
import { getAssignmentStatus } from '~/constants/assignments/assignmentStatusConfig';
import { getAssignmentType } from '~/constants/assignments/assignmentTypes';
import { getContractStatus } from '~/constants/contracts/contractStatusConfig';
import { getUserRole } from '~/constants/users/userRoles';

definePageMeta({
  backGroup: 'project-details',
  backLabel: 'project',
});

//TODO MB make avatar images bigger on mobile

interface Props {
  projectId: string;
  projectShortInfo?: ProjectShortInfo;
  tabStatus?: ProjectEditTabsStatusResponse;
}

const props = defineProps<Props>();

const route = useRoute();
const params = computed<ProjectAssignmentParams>(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );
  const urlParams: ProjectAssignmentParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as UserSortBy) || 'name',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'asc',
    search_query: (route.query.search_query as string) || undefined,
    assignment_statuses: processArrayQueryParameterFromUrl<AssignmentStatus>(route.query.assignment_statuses),
    assignment_types: processArrayQueryParameterFromUrl<AssignmentType>(route.query.assignment_types),
    contract_statuses: processArrayQueryParameterFromUrl<ContractStatus>(route.query.contract_statuses),
    roles: processArrayQueryParameterFromUrl<UserRole>(route.query.roles),
    subcontractor_company_ids,
    include_unassigned,
    onboarding_state: parseOnboardingStateFromQuery(route.query),
    project_onboarding_state: parseProjectOnboardingStateFromQuery(route.query),
  } satisfies ProjectCanvasserListRequest;

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as ProjectAssignmentParams;
});

const {
  data: projectAssignments,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => [
    'project-assignments',
    props.projectId,
    {
      ...params.value,
      onboarding_state: serializeOnboardingStateForKey(route.query),
      project_onboarding_state: serializeProjectOnboardingStateForKey(route.query),
    },
  ],
  query: () =>
    getProjectCanvasserList({
      composable: '$fetch',
      path: { project_id: props.projectId },
      body: params.value,
    }),
  enabled: () => !!props.projectId,
  staleTime: 0,
  placeholderData: (previousData) => previousData,
});

const items = computed(() => projectAssignments.value?.items ?? []);
const totalCount = computed(() => projectAssignments.value?.total_count ?? 0);
const allCount = computed(() => projectAssignments.value?.all_count ?? 0);
const assignmentStatusCount = computed(() => projectAssignments.value?.assignment_status_counts ?? {});
const onboardingMissingCounts = computed(() => projectAssignments.value?.onboarding_missing_counts ?? {});
const projectOnboardingMissingCounts = computed(
  () => projectAssignments.value?.project_onboarding_missing_counts ?? {}
);

const { data: projectDetails } = useQuery({
  key: () => ['project', props.projectId],
  query: () => getProjectDetails({ composable: '$fetch', path: { project_id: props.projectId } }),
  enabled: () => !!props.projectId,
});

const assignableProject = computed(() =>
  projectDetails.value && isAdminProjectDetails(projectDetails.value) ? projectDetails.value : null
);

const { data: unassignedUsersResponse, isLoading: isLoadingAssignableUsers } = useQuery({
  key: () => ['selector-unassigned-users', props.projectId],
  query: () =>
    getSelectorUserList({
      composable: '$fetch',
      query: {
        statuses: ['active'],
        not_assigned_project_ids: [props.projectId],
      },
    }),
  enabled: () => !!props.projectId && !!assignableProject.value,
  staleTime: 0,
});

const assignableUserItems = computed<SelectItem[]>(() =>
  (unassignedUsersResponse.value?.users ?? []).map((user) => ({
    name: `${user.first_name} ${user.last_name}`,
    value: user.id,
    // The role is what tells two same-named options apart now that every role is listed, so it gets
    // its own line instead of being run into the company name.
    caption: getUserRole(user.role).name,
    subtitle: user.subcontractor_short_info?.name,
  }))
);

const statusTabs = computed<NavigationItem[]>(() =>
  buildMultiSelectStatusTabs<AssignmentStatus>({
    source: filteredAssignmentStatusesForTabs(),
    current: params.value.assignment_statuses ?? [],
    allCount: allCount.value,
    counts: assignmentStatusCount.value,
    buildTo: (next) => ({
      name: 'projects-id-assignments',
      params: { id: props.projectId },
      query: { ...useRoute().query, page: 1, assignment_statuses: next.length ? next : undefined },
    }),
  })
);
</script>
