<template>
  <Dialog v-model:open="isOpen" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <Button :prepend-icon="UserPlusIcon" data-testid="project-assignments-assign-button">Assign User</Button>
    </DialogTrigger>
    <DialogContent class="gap-6 max-w-xs sm:max-w-sm md:max-w-5xl px-0">
      <DialogHeader class="px-6">
        <DialogTitle class="text-start">Assign User</DialogTitle>
        <DialogDescription> Select a user to assign to this project. </DialogDescription>
      </DialogHeader>

      <div class="px-6 max-w-md w-full min-w-0">
        <ComboboxSelector
          v-model="selectedUserId"
          :items="users"
          :loading="usersLoading || isLoadingUserDetails"
          placeholder="Select user"
          empty-text="No users found"
          clearable
          :icon="UserPlusIcon"
          data-testid="project-assignments-user-select"
        />
      </div>

      <form v-if="selectedUserDetails" id="assignNewProject" class="px-6 min-w-0" @submit.prevent="onSubmit">
        <AssignmentInfoForm
          :key="selectedUserDetails.id"
          mode="create"
          :user-id="selectedUserDetails.id"
          :user-role="selectedUserDetails.role"
          :user-full-name="username(selectedUserDetails)"
          :project-id="project.id"
          :project-name="project.name"
          :project-type="project.type"
          :payment="projectPayment"
        />
      </form>

      <DialogFooter class="flex flex-row justify-end gap-2 px-6">
        <DialogClose as-child>
          <Button variant="outline" class="h-10 px-4" :disabled="isAssigningUser">Cancel</Button>
        </DialogClose>
        <Button
          type="submit"
          form="assignNewProject"
          :loading="isAssigningUser"
          :disabled="!selectedUserDetails"
          data-testid="project-assignments-confirm-button"
        >
          Confirm Assignment
        </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { UserPlusIcon } from 'lucide-vue-next';
import { getUserDetails, type GetUserDetailsResponse, type ProjectDetailsForAdmin } from '~/client';

interface Props {
  project: ProjectDetailsForAdmin;
  users: SelectItem[];
  usersLoading?: boolean;
  assignmentsParams: ProjectAssignmentParams;
}

const props = defineProps<Props>();

const projectPayment = computed(() => props.project.pricing);

const isOpen = ref<boolean>(false);
const selectedUserId = ref<string | null>(null);

const { data: selectedUserDetails, isLoading: isLoadingUserDetails } = useQuery({
  key: () => ['selector-user-details', selectedUserId.value],
  query: (): Promise<GetUserDetailsResponse> =>
    getUserDetails({ composable: '$fetch', path: { user_id: selectedUserId.value! } }),
  enabled: () => !!selectedUserId.value,
});

const isRegularCanvasser = computed(() => selectedUserDetails.value?.role === 'canvasser');

const { applyDefaults, resetForm, submitAssignment, isAssigningUser } = useCanvasserAssignmentForm({
  projectType: () => props.project.type,
  payment: () => projectPayment.value,
  isRegularCanvasser,
  projectId: () => props.project.id,
  userId: () => selectedUserDetails.value?.id,
  userRole: () => selectedUserDetails.value?.role,
  assignmentsCacheParams: () => ({ scope: 'project', params: props.assignmentsParams }),
  onAssigned: () => {
    isOpen.value = false;
  },
});

watch(
  () => selectedUserDetails.value?.id,
  (id) => {
    if (id) {
      applyDefaults();
    }
  }
);

const onSubmit = submitAssignment;

function onOpenUpdate(open: boolean) {
  if (!open) {
    resetForm();
  }
  selectedUserId.value = null;
}

onUnmounted(() => {
  selectedUserId.value = null;
});
</script>

<style scoped lang="scss"></style>
