import type { SortType, UserSortBy, UserToProjectLinkSortBy } from '~/client';

// The project-canvasser-list endpoint accepts a union of two sort enums
// (`sort_by: UserSortBy | UserToProjectLinkSortBy`), which is why `pay_rate`
// (UserToProjectLinkSortBy) and `name` (UserSortBy) are both valid here.
export const assignmentsSortBy: SelectItem<`${UserSortBy | UserToProjectLinkSortBy}|${SortType}`>[] = [
  { name: 'Name (A-Z)', value: 'name|asc' },
  { name: 'Name (Z-A)', value: 'name|desc' },
  { name: 'Highest pay rate', value: 'pay_rate|desc' },
  { name: 'Lowest pay rate', value: 'pay_rate|asc' },
];
