<template>
  <Alert v-if="items.length" variant="warning">
    <TriangleAlert class="size-5" />
    <AlertTitle>Onboarding issues</AlertTitle>
    <AlertDescription>
      Some assigned canvassers have incomplete onboarding. Select a step to see who's missing it.
    </AlertDescription>
    <div class="mt-3 flex flex-wrap gap-2">
      <NuxtLink
        v-for="item in items"
        :key="item.checkmark"
        :to="buildTo(item.checkmark)"
        :aria-label="`Filter by ${item.label} — ${item.count} canvassers missing`"
      >
        <Badge variant="warning" size="md" class="gap-1.5 normal-case hover:opacity-80">
          {{ item.label }}
          <span class="font-semibold">{{ item.count }}</span>
        </Badge>
      </NuxtLink>
    </div>
  </Alert>
</template>

<script setup lang="ts">
import { TriangleAlert } from 'lucide-vue-next';
import type { OnboardingFlag, ProjectCanvasserResponse } from '~/client';

interface Props {
  missingCounts: ProjectCanvasserResponse['onboarding_missing_counts'];
  projectId: string;
}

const props = defineProps<Props>();

const items = computed(() => getMissingOnboardingCounts(props.missingCounts));

function buildTo(checkmark: OnboardingFlag) {
  return {
    name: 'projects-id-assignments',
    params: { id: props.projectId },
    query: { [checkmark]: 'false' },
  };
}
</script>
